"use client";

import { useMemo, useState } from "react";
import { ChevronDown, Search, SlidersHorizontal } from "lucide-react";
import { cn } from "@/lib/utils";

const categories = ["All", "Getting Started", "Billing", "Features", "Support"];

const faqs = [
  { q: "What is Shilp UI?", a: "Shilp UI is a premium React component library designed around a refined dark interface system.", c: "Getting Started" },
  { q: "How do I install Shilp UI?", a: "Install the required dependencies and copy the component into your project.", c: "Getting Started" },
  { q: "Can I customize the components?", a: "Yes. Components are designed to be easily customized with Tailwind CSS.", c: "Features" },
  { q: "Do you offer a free version?", a: "Yes. Core components can be used freely in your projects.", c: "Billing" },
  { q: "Can I use Shilp in production?", a: "Yes. The components are designed for real-world applications and production interfaces.", c: "Features" },
  { q: "Where can I get support?", a: "Use the project documentation or contact the support team for help.", c: "Support" },
];

export default function Faq01() {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("All");
  const [open, setOpen] = useState<number | null>(0);

  const filtered = useMemo(
    () =>
      faqs.filter(
        (item) =>
          (category === "All" || item.c === category) &&
          `${item.q} ${item.a}`.toLowerCase().includes(query.toLowerCase())
      ),
    [query, category]
  );

  return (
    <section className="w-full bg-[#050506] px-4 py-16 text-white sm:px-6 lg:px-8">
      <div className="mx-auto max-w-4xl">
        <div className="mb-10 text-center">
          <div className="mb-4 inline-flex items-center gap-2 rounded-full border border-white/[0.08] bg-white/[0.03] px-3 py-1.5 text-xs text-zinc-400">
            <SlidersHorizontal className="h-3.5 w-3.5 text-violet-300" />
            Help Center
          </div>
          <h2 className="text-3xl font-semibold tracking-tight sm:text-4xl">
            Frequently asked questions
          </h2>
          <p className="mx-auto mt-3 max-w-xl text-sm leading-6 text-zinc-500">
            Everything you need to know before getting started.
          </p>
        </div>

        <div className="mb-6 flex flex-col gap-3 sm:flex-row">
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-zinc-600" />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search questions..."
              className="h-11 w-full rounded-xl border border-white/[0.08] bg-white/[0.025] pl-11 pr-4 text-sm text-zinc-200 outline-none transition placeholder:text-zinc-600 focus:border-violet-400/40 focus:bg-white/[0.04]"
            />
          </div>
        </div>

        <div className="mb-6 flex gap-2 overflow-x-auto pb-1">
          {categories.map((item) => (
            <button
              key={item}
              onClick={() => setCategory(item)}
              className={cn(
                "whitespace-nowrap rounded-full border px-3 py-1.5 text-xs transition",
                category === item
                  ? "border-violet-400/30 bg-violet-400/10 text-violet-200"
                  : "border-white/[0.07] bg-white/[0.02] text-zinc-500 hover:border-white/[0.12] hover:text-zinc-300"
              )}
            >
              {item}
            </button>
          ))}
        </div>

        <div className="overflow-hidden rounded-2xl border border-white/[0.07] bg-white/[0.018]">
          {filtered.map((item, index) => (
            <div key={item.q} className="border-b border-white/[0.06] last:border-0">
              <button
                onClick={() => setOpen(open === index ? null : index)}
                className="flex w-full items-center justify-between gap-5 px-5 py-5 text-left"
              >
                <span className="text-sm font-medium text-zinc-200">{item.q}</span>
                <ChevronDown
                  className={cn(
                    "h-4 w-4 shrink-0 text-zinc-600 transition-transform",
                    open === index && "rotate-180 text-violet-300"
                  )}
                />
              </button>

              {open === index && (
                <div className="px-5 pb-5 pr-12 text-sm leading-6 text-zinc-500">
                  {item.a}
                </div>
              )}
            </div>
          ))}

          {!filtered.length && (
            <div className="px-5 py-12 text-center text-sm text-zinc-600">
              No questions found.
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { ChevronDown, Mail } from "lucide-react";

const faqs = [
  ["How does Shilp UI work?", "Shilp UI provides reusable React components built around a consistent design language."],
  ["Can I customize the styling?", "Yes. Every component is designed to work naturally with Tailwind CSS."],
  ["Is it responsive?", "Yes. The layout adapts across mobile, tablet and desktop screens."],
  ["Can I use the components commercially?", "Yes. You can adapt the components to your own projects."],
];

export default function Faq02() {
  const [open, setOpen] = useState<number | null>(0);

  return (
    <section className="w-full bg-[#050506] px-4 py-16 text-white sm:px-6">
      <div className="mx-auto max-w-3xl">
        <div className="mb-8">
          <span className="text-[10px] font-semibold uppercase tracking-[0.2em] text-violet-300">
            FAQ
          </span>
          <h2 className="mt-3 text-3xl font-semibold tracking-tight">
            Answers, without the noise.
          </h2>
        </div>

        <div className="space-y-2">
          {faqs.map(([question, answer], index) => {
            const active = open === index;

            return (
              <div
                key={question}
                className="overflow-hidden rounded-xl border border-white/[0.07] bg-white/[0.02]"
              >
                <button
                  onClick={() => setOpen(active ? null : index)}
                  className="flex w-full items-center justify-between gap-5 px-5 py-5 text-left"
                >
                  <span className="text-sm font-medium text-zinc-200">
                    {question}
                  </span>
                  <ChevronDown
                    className={`h-4 w-4 shrink-0 text-zinc-600 transition-transform duration-300 ${
                      active ? "rotate-180 text-violet-300" : ""
                    }`}
                  />
                </button>

                <AnimatePresence initial={false}>
                  {active && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: "auto", opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.25 }}
                    >
                      <p className="px-5 pb-5 text-sm leading-6 text-zinc-500">
                        {answer}
                      </p>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            );
          })}
        </div>

        <div className="mt-6 flex items-center justify-between rounded-xl border border-white/[0.07] bg-white/[0.02] p-4">
          <div>
            <p className="text-sm font-medium text-zinc-200">Still have questions?</p>
            <p className="mt-1 text-xs text-zinc-600">Our team is happy to help.</p>
          </div>
          <button className="flex items-center gap-2 rounded-full bg-white px-4 py-2 text-xs font-medium text-black transition hover:bg-zinc-200">
            <Mail className="h-3.5 w-3.5" />
            Contact
          </button>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import { ChevronDown, MessageCircle } from "lucide-react";

const groups = [
  {
    title: "Getting Started",
    items: [
      ["How do I start?", "Install the required dependencies and import the component you need."],
      ["Is Shilp beginner friendly?", "Yes. Components use familiar React and Tailwind patterns."],
    ],
  },
  {
    title: "Features",
    items: [
      ["Are components responsive?", "Yes. Components are designed for responsive interfaces."],
      ["Can I change colors?", "Yes. Tailwind utilities make visual customization straightforward."],
    ],
  },
  {
    title: "Support",
    items: [
      ["Where can I ask questions?", "Use your project's documentation or support channel."],
    ],
  },
];

export default function Faq03() {
  const [open, setOpen] = useState<string | null>(null);

  return (
    <section className="w-full bg-[#050506] px-4 py-16 text-white">
      <div className="mx-auto max-w-4xl">
        <div className="mb-10">
          <p className="text-xs font-medium text-violet-300">KNOWLEDGE BASE</p>
          <h2 className="mt-3 text-3xl font-semibold">Common questions</h2>
        </div>

        <div className="space-y-8">
          {groups.map((group) => (
            <div key={group.title}>
              <div className="mb-3 flex items-center justify-between">
                <h3 className="text-sm font-medium text-zinc-200">{group.title}</h3>
                <span className="rounded-full border border-white/[0.06] px-2 py-1 text-[10px] text-zinc-600">
                  {group.items.length} topics
                </span>
              </div>

              <div className="overflow-hidden rounded-xl border border-white/[0.07]">
                {group.items.map(([q, a]) => {
                  const id = `${group.title}-${q}`;
                  const active = open === id;

                  return (
                    <div key={id} className="border-b border-white/[0.06] last:border-0">
                      <button
                        onClick={() => setOpen(active ? null : id)}
                        className="flex w-full items-center justify-between px-5 py-4 text-left"
                      >
                        <span className="text-sm text-zinc-300">{q}</span>
                        <ChevronDown
                          className={`h-4 w-4 text-zinc-600 transition ${
                            active ? "rotate-180 text-violet-300" : ""
                          }`}
                        />
                      </button>

                      {active && (
                        <p className="px-5 pb-5 text-sm leading-6 text-zinc-500">
                          {a}
                        </p>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>

        <div className="mt-10 flex items-center gap-3 text-xs text-zinc-500">
          <MessageCircle className="h-4 w-4 text-violet-300" />
          Can't find what you're looking for?
        </div>
      </div>
    </section>
  );
}

