"use client";

import { useState } from "react";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";

const categories = ["Overview", "Account", "Billing", "Features", "Support"];

const data: Record<string, [string, string][]> = {
  Overview: [
    ["What is Shilp?", "A reusable UI system for modern React applications."],
    ["What does it include?", "A collection of reusable interface components."],
  ],
  Account: [
    ["Can I create multiple projects?", "Yes. Components can be reused across projects."],
    ["Can I customize components?", "Yes. Tailwind classes make customization simple."],
  ],
  Billing: [
    ["Is there a free option?", "Yes. Core components can be used freely."],
  ],
  Features: [
    ["Are components responsive?", "Yes. Responsive behavior is built into the layouts."],
  ],
  Support: [
    ["How do I get help?", "Use your project's support or documentation channel."],
  ],
};

export default function Faq04() {
  const [category, setCategory] = useState("Overview");
  const [open, setOpen] = useState<number | null>(0);

  return (
    <section className="w-full bg-[#050506] px-4 py-16 text-white sm:px-6">
      <div className="mx-auto grid max-w-5xl gap-8 md:grid-cols-[220px_1fr]">
        <aside className="md:sticky md:top-8 md:self-start">
          <p className="mb-3 text-[10px] font-semibold uppercase tracking-[0.18em] text-zinc-600">
            Documentation
          </p>

          <div className="space-y-1">
            {categories.map((item) => (
              <button
                key={item}
                onClick={() => {
                  setCategory(item);
                  setOpen(0);
                }}
                className={cn(
                  "flex w-full items-center rounded-xl px-3 py-2.5 text-left text-sm transition",
                  category === item
                    ? "bg-white/[0.05] text-white"
                    : "text-zinc-600 hover:bg-white/[0.025] hover:text-zinc-300"
                )}
              >
                {item}
                {category === item && (
                  <span className="ml-auto h-1.5 w-1.5 rounded-full bg-violet-400" />
                )}
              </button>
            ))}
          </div>
        </aside>

        <div>
          <div className="mb-7">
            <span className="text-xs text-violet-300">{category}</span>
            <h2 className="mt-2 text-3xl font-semibold">Frequently asked questions</h2>
          </div>

          <div className="overflow-hidden rounded-2xl border border-white/[0.07] bg-white/[0.018]">
            {data[category].map(([q, a], index) => {
              const active = open === index;

              return (
                <div key={q} className="border-b border-white/[0.06] last:border-0">
                  <button
                    onClick={() => setOpen(active ? null : index)}
                    className="flex w-full items-center justify-between px-5 py-5 text-left"
                  >
                    <span className="text-sm font-medium text-zinc-200">{q}</span>
                    <ChevronDown
                      className={cn(
                        "h-4 w-4 text-zinc-600 transition",
                        active && "rotate-180 text-violet-300"
                      )}
                    />
                  </button>

                  {active && (
                    <div className="px-5 pb-5 text-sm leading-6 text-zinc-500">
                      {a}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import { Plus, Minus } from "lucide-react";

const faqs = [
  ["What makes Shilp different?", "Shilp focuses on consistency without repetition, giving every component a shared visual language while preserving its purpose."],
  ["Does Shilp support dark interfaces?", "Dark interfaces are at the center of the Shilp visual system."],
  ["Can components be composed together?", "Yes. Components are designed to work as building blocks for larger interfaces."],
  ["Is motion required?", "No. Motion is restrained and can be removed or customized according to the application."],
];

export default function Faq06() {
  const [open, setOpen] = useState<number | null>(0);

  return (
    <section className="w-full bg-[#050506] px-4 py-16 text-white">
      <div className="mx-auto max-w-3xl">
        <h2 className="mb-8 text-3xl font-semibold tracking-tight">
          Questions worth asking.
        </h2>

        <div className="space-y-3">
          {faqs.map(([q, a], index) => {
            const active = open === index;

            return (
              <div
                key={q}
                className={`rounded-2xl border transition ${
                  active
                    ? "border-violet-400/20 bg-white/[0.035]"
                    : "border-white/[0.07] bg-white/[0.018]"
                }`}
              >
                <button
                  onClick={() => setOpen(active ? null : index)}
                  className="flex w-full items-center gap-4 px-5 py-5 text-left"
                >
                  <span
                    className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full border ${
                      active
                        ? "border-violet-400/30 bg-violet-400/10 text-violet-300"
                        : "border-white/[0.08] text-zinc-600"
                    }`}
                  >
                    {active ? <Minus className="h-3 w-3" /> : <Plus className="h-3 w-3" />}
                  </span>

                  <span className="text-sm font-medium text-zinc-200">{q}</span>
                </button>

                {active && (
                  <div className="border-t border-white/[0.06] px-5 py-5 pl-16 text-sm leading-6 text-zinc-500">
                    {a}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import { Minus, Plus, ArrowUpRight } from "lucide-react";

const faqs = [
  ["How do I install it?", "Add the component to your React project and install any required dependencies."],
  ["Can I change the visual system?", "Yes. Tailwind makes it easy to adjust spacing, typography, colors and surfaces."],
  ["Is Shilp mobile friendly?", "Every layout is designed to collapse naturally on smaller screens."],
  ["Can I build an entire product with it?", "The components are intended to work together as a reusable design system."],
];

export default function Faq07() {
  const [open, setOpen] = useState<number | null>(0);

  return (
    <section className="w-full bg-[#050506] px-4 py-16 text-white sm:px-6">
      <div className="mx-auto grid max-w-5xl gap-12 md:grid-cols-[0.8fr_1.2fr]">
        <div className="md:sticky md:top-10 md:self-start">
          <span className="text-xs font-medium text-violet-300">SUPPORT</span>
          <h2 className="mt-3 text-3xl font-semibold tracking-tight">
            We made the answers simple.
          </h2>
          <p className="mt-4 max-w-sm text-sm leading-6 text-zinc-500">
            Find answers to common questions about using Shilp UI.
          </p>

          <button className="mt-6 inline-flex items-center gap-2 rounded-full border border-white/[0.08] bg-white/[0.025] px-4 py-2.5 text-xs text-zinc-300 transition hover:border-white/[0.14] hover:text-white">
            Visit documentation
            <ArrowUpRight className="h-3.5 w-3.5" />
          </button>
        </div>

        <div className="space-y-2">
          {faqs.map(([q, a], index) => {
            const active = open === index;

            return (
              <div
                key={q}
                className="rounded-xl border border-white/[0.07] bg-white/[0.02]"
              >
                <button
                  onClick={() => setOpen(active ? null : index)}
                  className="flex w-full items-center justify-between px-5 py-5 text-left"
                >
                  <span className="text-sm text-zinc-200">{q}</span>
                  {active ? (
                    <Minus className="h-4 w-4 text-violet-300" />
                  ) : (
                    <Plus className="h-4 w-4 text-zinc-600" />
                  )}
                </button>

                {active && (
                  <p className="px-5 pb-5 text-sm leading-6 text-zinc-500">
                    {a}
                  </p>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import { Check, Layers3 } from "lucide-react";
import { cn } from "@/lib/utils";

const groups = {
  General: [
    ["What is Shilp?", "A reusable component system for modern applications."],
    ["Who is it for?", "Developers and teams building polished React interfaces."],
    ["Is it responsive?", "Yes. Components adapt to different screen sizes."],
  ],
  Design: [
    ["What style does Shilp use?", "A premium dark aesthetic with subtle glass surfaces and violet accents."],
    ["Can I customize it?", "Yes. Tailwind utilities make the visual system easy to adapt."],
  ],
  Development: [
    ["Can I copy individual components?", "Yes. Components are intentionally modular."],
    ["Does it work with Next.js?", "Yes. The components are suitable for Next.js applications."],
  ],
};

export default function Faq08() {
  const [tab, setTab] = useState<keyof typeof groups>("General");

  return (
    <section className="w-full bg-[#050506] px-4 py-16 text-white">
      <div className="mx-auto max-w-5xl">
        <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end">
          <div>
            <div className="mb-3 flex items-center gap-2 text-xs text-violet-300">
              <Layers3 className="h-4 w-4" />
              FAQ Library
            </div>
            <h2 className="text-3xl font-semibold">Explore by topic</h2>
          </div>

          <div className="flex rounded-full border border-white/[0.07] bg-white/[0.02] p-1">
            {Object.keys(groups).map((item) => (
              <button
                key={item}
                onClick={() => setTab(item as keyof typeof groups)}
                className={cn(
                  "rounded-full px-3 py-1.5 text-xs transition",
                  tab === item
                    ? "bg-white text-black"
                    : "text-zinc-600 hover:text-zinc-300"
                )}
              >
                {item}
              </button>
            ))}
          </div>
        </div>

        <div className="grid gap-3 md:grid-cols-2">
          {groups[tab].map(([q, a]) => (
            <div
              key={q}
              className="rounded-2xl border border-white/[0.07] bg-white/[0.02] p-6 transition hover:border-white/[0.12]"
            >
              <div className="mb-4 flex h-8 w-8 items-center justify-center rounded-xl border border-violet-400/15 bg-violet-400/[0.06]">
                <Check className="h-3.5 w-3.5 text-violet-300" />
              </div>
              <h3 className="text-sm font-medium text-zinc-200">{q}</h3>
              <p className="mt-3 text-sm leading-6 text-zinc-500">{a}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useMemo, useState } from "react";
import { ChevronRight, Search, LifeBuoy } from "lucide-react";

const faqs = [
  ["How do I get started with Shilp?", "Choose a component, copy it into your project and customize it to your needs."],
  ["Can I use Shilp with Tailwind?", "Yes. Tailwind is central to the component styling."],
  ["Are the components accessible?", "The interactive components use standard buttons, inputs and keyboard-friendly controls."],
  ["Where are the components located?", "Keep your components organized in your project's preferred component directory."],
  ["Can I create my own components?", "Absolutely. Follow the Shilp visual language to extend the library."],
];

export default function Faq09() {
